const SND={};function sndLoad(k,u){if(SND[k])return;try{if(!AC)AC=new (window.AudioContext||window.webkitAudioContext)();}catch(e){return;}const o=SND[k]={b:null,v:[],q:[]};fetch(u).then(r=>{if(!r.ok)throw 0;return r.arrayBuffer();}).then(ab=>new Promise((res,rej)=>AC.decodeAudioData(ab,res,rej))).then(b=>{o.b=b;const q=o.q.splice(0);q.forEach(x=>{if(performance.now()-x[2]<1800)sndPlay(k,x[0],x[1]);});}).catch(()=>{o.bad=1;const q=o.q.splice(0);if(q.length&&o.fb)o.fb();});}
function sndPlay(k,vol,max){const o=SND[k];if(!o||o.bad||!AC)return 0;if(!o.b){if(o.q.length<3)o.q.push([vol,max,performance.now()]);return -1;}o.v=o.v.filter(x=>!x.done);while(o.v.length>=max){const x=o.v.shift();try{const t=AC.currentTime;x.g.gain.cancelScheduledValues(t);x.g.gain.setValueAtTime(x.g.gain.value,t);x.g.gain.linearRampToValueAtTime(0,t+.45);x.n.stop(t+.5);}catch(e){}}const n=AC.createBufferSource(),g=AC.createGain();n.buffer=o.b;g.gain.value=vol;n.connect(g);g.connect(out());const x={n:n,g:g,done:false};n.onended=()=>{x.done=true;};n.start();o.v.push(x);return o.b.duration;}
